# rand7() is provided by the judge: it returns a uniform integer in [1, 7]
class Solution:
    def rand10(self) -> int:
        while True:
            idx = (rand7() - 1) * 7 + rand7()    # uniform over 1..49
            if idx <= 40:                        # reject 41..49 so 40 outcomes split evenly
                return 1 + (idx - 1) % 10
